      originalIntent: null,
      turnIntents: [],
      toolHistory: [],
      currentTurn: 0,
      driftDetector: eph.driftDetector,
      originalEmbedding: null,
      filesWritten: new Map(),
      filesRead: [],
      envVars: new Map(),
      turnMetrics: [],
