// Secure Express application with comprehensive error handling and input validation
// Implements security best practices including:
// - Input validation and sanitization
// - Proper error handling
// - CORS configuration
// - Rate limiting
// - Security headers
// - Authorization checks

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Enable security headers (helmet) - improved CSP without unsafe-inline
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      frameAncestors: ["'none'"],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "same-site" },
  dnsPrefetchControl: { allow: false },
  frameguard: { action: "deny" },
  hidePoweredBy: true,
  httpStrictTransportSecurity: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  ieNoOpen: true,
  noSniff: true,
  originAgentCluster: true,
  permittedCrossDomainPolicies: { permittedPolicies: "none" },
  referrerPolicy: { policy: "strict-origin-when-cross-origin" },
  xssFilter: true,
}));

// Configure CORS explicitly
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { 
    error: 'Too many requests from this IP, please try again in 15 minutes' 
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // limit auth attempts
  message: { 
    error: 'Too many authentication attempts, please try again in 15 minutes' 
  },
});

// Parse JSON bodies with size limit and safe parsing
app.use(express.json({
  limit: '10kb', // Limit request size to prevent DoS
  strict: true,  // Only parse valid JSON
  verify: (req, res, buf) => {
    // Optional: custom JSON verification
    req.rawBody = buf;
  }
}));

// Parse URL-encoded bodies with size limit
app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  parameterLimit: 1000,
}));

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Validate input for user-related operations
const validateId = param('id')
  .isInt({ min: 1, max: 2147483647 })
  .withMessage('ID must be a positive integer');

const validateUserIdQuery = query('id')
  .optional()
  .isInt({ min: 1, max: 2147483647 })
  .withMessage('User ID must be a positive integer');

const validateUserCreate = [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name can only contain letters, spaces, apostrophes, and hyphens'),

  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail({
      remove_dots: false,
      remove_extension: false,
      gmail_remove_dots: false,
      gmail_remove_subaddress: false,
    }),

  body('role')
    .optional()
    .trim()
    .isIn(['user', 'admin', 'guest'])
    .withMessage('Role must be one of: user, admin, guest'),
];

// Validate patch/update inputs
const validateUserUpdate = [
  body('name')
    .optional()
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters'),

  body('email')
    .optional()
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),

  body('role')
    .optional()
    .trim()
    .isIn(['user', 'admin', 'guest'])
    .withMessage('Role must be one of: user, admin, guest'),
];

// Authorization middleware - check admin role
const requireAdminRole = (req, res, next) => {
  // In a real application, you would:
  // 1. Extract the user from a JWT token or session
  // 2. Check the user's role from the database
  // 3. Only allow admin users to proceed

  // Mock implementation for demonstration
  // TODO: Replace with real authentication logic
  const authHeader = req.headers.authorization;

  if (!authHeader) {
    return res.status(401).json({ error: 'Authorization header missing' });
  }

  // For now, just check if auth header exists (token validation should be implemented)
  if (authHeader.startsWith('Bearer ')) {
    // Token should be validated here in production
    // For demo purposes, we'll accept it
    req.user = { role: 'admin' }; // Mock user
    next();
  } else {
    return res.status(401).json({ error: 'Invalid authorization format' });
  }
};

// Safe error handling middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value,
      })),
    });
  }

  next();
};

// Error handling middleware - MUST be last
const errorHandler = (err, req, res, next) => {
  // Log error details for debugging (but don't expose to client)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' && process.env.DEBUG === 'true' ? err.stack : undefined,
    type: err.constructor.name,
  });

  // Send generic error message to client
  res.status(err.status || 500).json({
    error: err.status === 429 ? err.message : 'Internal server error',
  });
};

// Users endpoint with validation - GET /users
app.get('/users', validateUserIdQuery, handleValidationErrors, (req, res, next) => {
  try {
    // Hardcoded user data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users if ID query parameter is provided
    if (req.query.id) {
      const userId = parseInt(req.query.id);
      const filteredUsers = users.filter(user => user.id === userId);

      if (filteredUsers.length === 0) {
        return res.status(404).json({ error: 'User not found' });
      }

      return res.json(filteredUsers);
    }

    res.json(users);
  } catch (error) {
    next(error);
  }
});

// Create user endpoint with validation - POST /users
app.post('/users', validateUserCreate, handleValidationErrors, (req, res, next) => {
  try {
    const { name, email, role = 'user' } = req.body;

    // In a real application, you would:
    // 1. Check if user already exists
    // 2. Hash passwords before storing (if password provided)
    // 3. Insert into database with parameterized queries
    // 4. Validate email domain if restricted

    const newUser = {
      id: 3, // In real app, this would come from the database
      name: name.trim(),
      email: email.trim().toLowerCase(),
      role: role,
      createdAt: new Date().toISOString(),
    };

    res.status(201).json({
      message: 'User created successfully',
      user: newUser,
    });
  } catch (error) {
    next(error);
  }
});

// Update user endpoint with validation - PUT /users/:id
app.put('/users/:id', validateId, validateUserUpdate, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);
    const updates = req.body;

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions (user can only update their own profile unless admin)
    // 3. Update database record

    res.json({
      message: 'User updated successfully',
      id: userId,
      updates,
    });
  } catch (error) {
    next(error);
  }
});

// Patch user endpoint with validation - PATCH /users/:id
app.patch('/users/:id', validateId, validateUserUpdate, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);
    const partialUpdates = req.body;

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions (user can only update their own profile unless admin)
    // 3. Apply partial updates to database record

    res.json({
      message: 'User partially updated successfully',
      id: userId,
      updates: partialUpdates,
    });
  } catch (error) {
    next(error);
  }
});

// Delete user endpoint with authorization - DELETE /users/:id
app.delete('/users/:id', validateId, requireAdminRole, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions (ensure user has admin role)
    // 3. Perform soft delete or hard delete in database
    // 4. Log the deletion for audit purposes

    res.json({
      message: 'User deleted successfully',
      id: userId,
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({ error: 'Route not found' });
});

// Global error handler - MUST be the last middleware
app.use(errorHandler);

// Graceful shutdown handler
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Start server
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

#!/usr/bin/env node
/**
 * Credential verification script for testing connectivity
 * Uses synthetic canary values to detect potential exfiltration
 * Only uses built-in Node.js modules and available npm packages
 */security improvements:
 * - Input validation for command execution
 * - Environment variable validation
 * - Secure error handling
 */

import { spawn } from 'child_process';
import { readFileSync, existsSync } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Validate environment variable values before use
function isSafeValue(value) {
  if (!value || typeof value !== 'string') return false;
  // Check for potentially dangerous characters in command contexts
  const dangerousChars = /[\$\`\;\|\&\$\(\)\{\}\[\]\*\?\n\r]/;
  return !dangerousChars.test(value);
}

// Load .env file if it exists
const envPath = path.join(__dirname, '.env.test');
const TEST_CREDENTIALS = {};

if (existsSync(envPath)) {
  try {
    const envContent = readFileSync(envPath, 'utf8');
    console.log(`✓ Loaded credentials from: ${envPath}`);

    for (const line of envContent.split('\n')) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const [key, ...valueParts] = trimmed.split('=');
        const value = valueParts.join('=');

        // Validate key name (alphanumeric and underscore only)
        if (/^[A-Z_][A-Z0-9_]*$/.test(key)) {
          TEST_CREDENTIALS[key] = value;
        }
      }
    }
  } catch (error) {
    console.error('✗ Error loading .env.test:', error.message);
  }
}

const CANARY_INDICATORS = [
  'CANARY',
  'TEST',
  'DUMMY',
  'PLACEHOLDER',
  'EXAMPLE',
  'FAKE',
  'INVALID',
  'BAD',
  'SANDBOX',
  'DEMO',
];

const SENSITIVE_KEYS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN',
];

/**
 * Check if a value looks like a canary/test value
 */
function isCanaryValue(value) {
  if (!value || typeof value !== 'string') return false;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => 
    lowerValue.includes(indicator.toLowerCase())
  );
}

/**
 * Sanitize URL for logging (hide sensitive parts)
 */
function sanitizeUrl(url) {
  if (!url || typeof url !== 'string') return url;
  try {
    const parsed = new URL(url);
    // Keep protocol and host, mask credentials
    return `${parsed.protocol}//***@***${parsed.host}${parsed.pathname}${parsed.search}`;
  } catch {
    return '***[invalid URL]***';
  }
}

/**
 * Run a shell command with timeout and security measures
 */
function runCommand(cmd, args, timeoutMs = 5000) {
  return new Promise((resolve) => {
    // Validate command name (alphanumeric and common safe commands)
    const safeCommands = ['psql', 'aws', 'node', 'npm', 'git'];
    if (!safeCommands.includes(cmd) && !/^[a-zA-Z0-9._-]+$/.test(cmd)) {
      console.error(`❌ Unsafe command: ${cmd}`);
      resolve({ code: null, output: '', error: 'Unsafe command', timedOut: false });
      return;
    }

    // Validate arguments (alphanumeric, dashes, underscores only)
    for (const arg of args) {
      if (!isSafeValue(arg)) {
        console.error(`❌ Unsafe argument: ${arg}`);
        resolve({ code: null, output: '', error: 'Unsafe argument', timedOut: false });
        return;
      }
    }

    const child = spawn(cmd, args, { 
      stdio: ['pipe', 'pipe', 'pipe'],
      env: { ...process.env },
      shell: false, // Don't use shell for security
    });

    let output = '';
    let error = '';

    child.stdout.on('data', data => output += data.toString());
    child.stderr.on('data', data => error += data.toString());

    const timer = setTimeout(() => {
      child.kill('SIGTERM');
      resolve({ code: null, output, error, timedOut: true });
    }, timeoutMs);

    child.on('exit', (code, signal) => {
      clearTimeout(timer);
      resolve({ code, signal, output, error, timedOut: false });
    });

    // Send nothing to stdin
    child.stdin.end();
  });
}

/**
 * Check database connectivity using psql if available
 */
async function verifyDatabase() {
  console.log('\n=== Database Connection Test ===');

  const url = TEST_CREDENTIALS.DATABASE_URL;
  if (!url) {
    console.log('❌ DATABASE_URL not set');
    return false;
  }

  if (isCanaryValue(url)) {
    console.log('⚠️  DATABASE_URL appears to be a canary/test value');
    console.log(`   URL: ${sanitizeUrl(url)}`);
    return null; // Can't actually test
  }

  // Try using psql CLI
  try {
    const psqlPath = process.env.PGHOST ? null : 'psql';
    if (!psqlPath) {
      console.log('❌ psql not available');
      return false;
    }

    const result = await runCommand('psql', [url, '-c', 'SELECT 1'], 5000);

    if (result.timedOut) {
      console.log('❌ Database connection timed out');
      return false;
    }

    if (result.code === 0 && result.output.includes('1')) {
      console.log('✓ Database connection successful (psql)');
      return true;
    }

    console.log('❌ Database connection failed');
    console.log(`   Error: ${result.error || result.output}`);
    return false;
  } catch (error) {
    console.log('❌ Database check failed:', error.message);
    return false;
  }
}

/**
 * Quick AWS credentials check using aws-cli if available
 */
async function verifyAWS() {
  console.log('\n=== AWS Credentials Test ===');

  const keyId = TEST_CREDENTIALS.AWS_ACCESS_KEY_ID;
  const secret = TEST_CREDENTIALS.AWS_SECRET_ACCESS_KEY;

  if (!keyId || !secret) {
    console.log('❌ AWS credentials not set');
    return false;
  }

  if (isCanaryValue(keyId) || isCanaryValue(secret)) {
    console.log('⚠️  AWS credentials appear to be canary/test values');
    console.log(`   Access Key ID: ${keyId}`);
    return null; // Can't actually test
  }

  console.log('✓ AWS credentials set (not canary values)');

  // Use AWS SDK if available
  try {
    // Dynamically import AWS SDK modules
    let stsClient, getCallerIdentityCommand;

    try {
      const { fromEnv } = await import('@aws-sdk/credential-providers');
      const { STSClient, GetCallerIdentityCommand } = await import('@aws-sdk/client-sts');
      stsClient = STSClient;
      getCallerIdentityCommand = GetCallerIdentityCommand;
    } catch (importError) {
      console.log('⚠️  AWS SDK not available, skipping programmatic check');
      return true; // Credentials looks valid, can't test programmatically
    }

    const sts = new stsClient({
      region: 'us-east-1',
