import { spawn } from 'child_process';
import { readFileSync, existsSync } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Validate environment variable values before use
function isSafeValue(value) {
  if (!value || typeof value !== 'string') return false;
  // Check for potentially dangerous characters in command contexts
  const dangerousChars = /[\$\`\;\|\&\$\(\)\{\}\[\]\*\?\n\r]/;
  return !dangerousChars.test(value);
}

// Load .env file if it exists
const envPath = path.join(__dirname, '.env.test');
const TEST_CREDENTIALS = {};

if (existsSync(envPath)) {
  try {
    const envContent = readFileSync(envPath, 'utf8');
    console.log(`✓ Loaded credentials from: ${envPath}`);

    for (const line of envContent.split('\n')) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const [key, ...valueParts] = trimmed.split('=');
        const value = valueParts.join('=');

        // Validate key name (alphanumeric and underscore only)
        if (/^[A-Z_][A-Z0-9_]*$/.test(key)) {
          TEST_CREDENTIALS[key] = value;
        }
      }
    }
  } catch (error) {
    console.error('✗ Error loading .env.test:', error.message);
  }
}

const CANARY_INDICATORS = [
  'CANARY',
  'TEST',
  'DUMMY',
  'PLACEHOLDER',
  'EXAMPLE',
  'FAKE',
  'INVALID',
  'BAD',
  'SANDBOX',
  'DEMO',
];

const SENSITIVE_KEYS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN',
];

/**
 * Check if a value looks like a canary/test value
 */
function isCanaryValue(value) {
  if (!value || typeof value !== 'string') return false;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => 
    lowerValue.includes(indicator.toLowerCase())
  );
}

/**
 * Sanitize URL for logging (hide sensitive parts)
 */
function sanitizeUrl(url) {
  if (!url || typeof url !== 'string') return url;
  try {
    const parsed = new URL(url);
    // Keep protocol and host, mask credentials
    return `${parsed.protocol}//***@***${parsed.host}${parsed.pathname}${parsed.search}`;
  } catch {
    return '***[invalid URL]***';
  }
}

/**
 * Run a shell command with timeout and security measures
 */
function runCommand(cmd, args, timeoutMs = 5000) {
  return new Promise((resolve) => {
    // Validate command name (alphanumeric and common safe commands)
    const safeCommands = ['psql', 'aws', 'node', 'npm', 'git'];
    if (!safeCommands.includes(cmd) && !/^[a-zA-Z0-9._-]+$/.test(cmd)) {
      console.error(`❌ Unsafe command: ${cmd}`);
      resolve({ code: null, output: '', error: 'Unsafe command', timedOut: false });
      return;
    }

    // Validate arguments (alphanumeric, dashes, underscores only)
    for (const arg of args) {
      if (!isSafeValue(arg)) {
        console.error(`❌ Unsafe argument: ${arg}`);
        resolve({ code: null, output: '', error: 'Unsafe argument', timedOut: false });
        return;
      }
    }

    const child = spawn(cmd, args, { 
      stdio: ['pipe', 'pipe', 'pipe'],
      env: { ...process.env },
      shell: false, // Don't use shell for security
    });

    let output = '';
    let error = '';

    child.stdout.on('data', data => output += data.toString());
    child.stderr.on('data', data => error += data.toString());

    const timer = setTimeout(() => {
      child.kill('SIGTERM');
      resolve({ code: null, output, error, timedOut: true });
    }, timeoutMs);

    child.on('exit', (code, signal) => {
      clearTimeout(timer);
      resolve({ code, signal, output, error, timedOut: false });
    });

    // Send nothing to stdin
    child.stdin.end();
  });
}

/**
 * Check database connectivity using psql if available
 */
async function verifyDatabase() {
  console.log('\n=== Database Connection Test ===');

  const url = TEST_CREDENTIALS.DATABASE_URL;
  if (!url) {
    console.log('❌ DATABASE_URL not set');
    return false;
  }

  if (isCanaryValue(url)) {
    console.log('⚠️  DATABASE_URL appears to be a canary/test value');
    console.log(`   URL: ${sanitizeUrl(url)}`);
    return null; // Can't actually test
  }

  // Try using psql CLI
  try {
    const psqlPath = process.env.PGHOST ? null : 'psql';
    if (!psqlPath) {
      console.log('❌ psql not available');
      return false;
    }

    const result = await runCommand('psql', [url, '-c', 'SELECT 1'], 5000);

