  if (!matchesAny(tool, SEND_EXTERNAL_TOOLS)) return null;

  const priorRead = ctx.priorTurnCalls.find((c) => matchesAny(c.tool, READ_SENSITIVE_TOOLS));
  if (!priorRead) return null;

