/**
 * PromptArmor Baseline
 *
 * Reproduces the PromptArmor (Shi et al., arXiv:2507.15219; ICLR 2026)
 * detector as a baseline for the head-to-head test plan. Single
 * surface: `screen(content, taskContext?)` runs the detector LLM on
 * one untrusted-content blob and returns a verdict + sanitised text.
 *
 * Architecture: this is NOT a tool-call interceptor. PromptArmor sits
 * upstream of the agent, scanning each tool result before it enters
 * the agent's context. See docs/test-plan-promptarmor-headtohead-2026-05-08.md
 * for how it plugs into the corpus runners.
 *
 * Output parsing follows Figure 2 of the paper:
 *   Line 1: "Yes" or "No"
 *   If Yes, line 2: "Injection: <verbatim text>"
 *
 * Sanitisation follows §3.1: tokenise the extracted injection, build
 * a regex with `.*?` between consecutive words, strip the first
 * (case-insensitive, dot-all) match from the data sample. If the regex
 * doesn't match, we still emit `verdict: "injected"` but leave the
 * sample unchanged and log a warning — the detector flagged it but we
 * couldn't locate the span.
 *
 * Per-call telemetry: when `runId` is set on the constructor, every
 * screen() appends a JSONL line to
 * `results/promptarmor/<runId>/calls.jsonl` with token counts, latency,
 * verdict, backend/model/temperature, and a SHA-256 of the input
 * content (so calls can be joined back to corpus items without
 * re-storing the full blob).
 */

import { appendFile } from "node:fs/promises";
import { existsSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { createHash } from "node:crypto";
import { bedrockChat } from "./bedrock-client.js";
import { openaiChat } from "./openai-client.js";
import { PROMPTARMOR_SYSTEM_PROMPT } from "./promptarmor-prompts.js";

export type PromptArmorBackend = "openai" | "bedrock";

export type PromptArmorVerdict = "clean" | "injected" | "parse_error";

export interface PromptArmorResult {
  verdict: PromptArmorVerdict;
  /** The (possibly sanitised) content. Equal to input when verdict=clean. */
  sanitised: string;
  latencyMs: number;
  tokens: { in: number; out: number };
  /** The detector's raw text output — useful for disagreement analysis. */
  rawOutput: string;
  /** When verdict=injected, the verbatim injection the detector flagged. */
  injection?: string;
  /** True when verdict=injected but the fuzzy regex didn't match the sample. */
  sanitisationFailed?: boolean;
}

export interface PromptArmorOpts {
  backend: PromptArmorBackend;
  /**
   * Detector model id. Caller's responsibility to map friendly names
   * (e.g. "gpt-4o" → "gpt-4o-2024-08-06") if desired.
   */
  model: string;
  /**
   * `"canonical"` would be a verbatim authors' release. Since none
   * exists as of 2026-05-08, we ship the reconstructed prompt and
   * accept this flag for forward-compatibility — both values currently
   * resolve to PROMPTARMOR_SYSTEM_PROMPT.
   */
  promptVersion?: "canonical" | "reconstructed";
  /** Detector temperature; paper uses 0. */
  temperature?: number;
  /**
   * Optional run id. When set, every screen() appends to
   * results/promptarmor/<runId>/calls.jsonl. Also seeds the sentinel
   * string so corpus runs can grep for it without colliding with prior
   * runs' output.
   */
  runId?: string;
  /** Override results directory; default `results/`. */
  resultsDir?: string;
}

interface CallLogEntry {
  ts: string;
  verdict: PromptArmorVerdict;
  backend: PromptArmorBackend;
  model: string;
  temperature: number;
  latency_ms: number;
  prompt_tokens: number;
  completion_tokens: number;
  content_hash: string;
  content_length: number;
  task_context_length: number;
  finish_reason?: string;
  parse_failure?: string;
  sanitisation_failed?: boolean;
}

export class PromptArmorBaseline {
  private readonly backend: PromptArmorBackend;
  private readonly model: string;
  private readonly temperature: number;
  private readonly runId: string | null;
  private readonly callLogPath: string | null;
  private readonly sentinel: string;

  constructor(opts: PromptArmorOpts) {
    this.backend = opts.backend;
    this.model = opts.model;
    this.temperature = opts.temperature ?? 0;
    this.runId = opts.runId ?? null;

    if (this.runId) {
      const baseDir = opts.resultsDir ?? "results";
      const dir = join(baseDir, "promptarmor", this.runId);
      if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
      this.callLogPath = join(dir, "calls.jsonl");
    } else {
      this.callLogPath = null;
    }

    // Run-scoped sentinel so a corpus blob that happens to contain the
    // sentinel literal from a previous run doesn't get false-stripped.
    this.sentinel = `[PROMPTARMOR-${this.runId ?? "adhoc"}-REDACTED]`;
  }

  /**
   * Screen a single untrusted-content blob.
   *
   * @param content - the data sample (typically a tool-result string)
   *   that the agent is about to consume.
   * @param taskContext - optional snippet of the user task. NOT used
   *   in the canonical PromptArmor prompt — included for forward
   *   compatibility if a future variant wants task-aware framing. Currently
   *   ignored by the detector but logged for telemetry.
   */
  async screen(content: string, taskContext?: string): Promise<PromptArmorResult> {
    const start = Date.now();
    const contentHash = sha256(content);

    let rawOutput: string;
    let inputTokens: number;
    let outputTokens: number;
    let finishReason = "unknown";

    try {
      if (this.backend === "openai") {
        const r = await openaiChat(PROMPTARMOR_SYSTEM_PROMPT, content, this.model, {
          temperature: this.temperature,
        });
        rawOutput = r.content;
        inputTokens = r.inputTokens;
        outputTokens = r.outputTokens;
        finishReason = r.finishReason;
      } else {
        // Bedrock: bedrockChat's temperature is tied to its `effort` flag,
        // and uses 0.1 by default. PromptArmor needs temperature 0
        // (paper §4.1) for reproducibility — but bedrockChat's surface
        // doesn't expose temperature directly. We rely on its
        // "no-effort" branch which sets temperature 0.1, and accept the
        // small temperature mismatch with the paper's GPT runs. Logged
        // in the call log so the disagreement analysis can account for
        // it.
        //
        // TODO(promptarmor): when bedrock-client.ts grows a temperature
        // override (it's already needed for the judge in some configs),
        // pass this.temperature through.
        const r = await bedrockChat(PROMPTARMOR_SYSTEM_PROMPT, content, this.model);
        rawOutput = r.content;
        inputTokens = r.inputTokens;
        outputTokens = r.outputTokens;
      }
    } catch (err) {
      // Network/auth failure. Surface to caller but log so the corpus
      // run can decide whether to retry.
      const msg = err instanceof Error ? err.message : String(err);
      console.warn(`  [promptarmor] backend ${this.backend} call failed: ${msg}`);
      throw err;
    }

    const latencyMs = Date.now() - start;
    const parsed = parseDetectorOutput(rawOutput);
    let result: PromptArmorResult;

    if (parsed.kind === "no") {
      result = {
        verdict: "clean",
        sanitised: content,
        latencyMs,
        tokens: { in: inputTokens, out: outputTokens },
        rawOutput,
      };
    } else if (parsed.kind === "yes") {
      const { sanitised, matched } = fuzzyStrip(content, parsed.injection);
      result = {
        verdict: "injected",
        sanitised: matched ? sanitised : content,
        latencyMs,
        tokens: { in: inputTokens, out: outputTokens },
        rawOutput,
        injection: parsed.injection,
        sanitisationFailed: !matched,
      };
      if (!matched) {
        console.warn(
          `  [promptarmor] detector returned Yes but fuzzy regex did not match content; verdict=injected, sample unchanged`,
        );
      }
    } else {
      result = {
        verdict: "parse_error",
        sanitised: content,
        latencyMs,
        tokens: { in: inputTokens, out: outputTokens },
        rawOutput,
      };
      console.warn(
        `  [promptarmor] could not parse detector output (${parsed.reason}); verdict=parse_error, treating as clean`,
      );
    }

    if (this.callLogPath) {
      const entry: CallLogEntry = {
        ts: new Date().toISOString(),
        verdict: result.verdict,
        backend: this.backend,
        model: this.model,
        temperature: this.temperature,
        latency_ms: latencyMs,
        prompt_tokens: inputTokens,
        completion_tokens: outputTokens,
        content_hash: contentHash,
        content_length: content.length,
        task_context_length: taskContext?.length ?? 0,
        finish_reason: finishReason,
        parse_failure: parsed.kind === "unparseable" ? parsed.reason : undefined,
        sanitisation_failed: result.sanitisationFailed,
      };
      // Best-effort; failure here doesn't break the screen.
      appendFile(this.callLogPath, JSON.stringify(entry) + "\n").catch((err) => {
        console.warn(`  [promptarmor] call log append failed: ${err}`);
      });
    }

    return result;
  }

  /** The sentinel string used for redactions — useful for collision pre-checks. */
  getSentinel(): string {
    return this.sentinel;
  }
}

// ---------------------------------------------------------------------------
// Output parser (Figure 2)
// ---------------------------------------------------------------------------

type ParseResult =
  | { kind: "yes"; injection: string }
  | { kind: "no" }
  | { kind: "unparseable"; reason: string };

function parseDetectorOutput(raw: string): ParseResult {
  const trimmed = raw.trim();
  if (!trimmed) return { kind: "unparseable", reason: "empty output" };

  // Strip common LLM dressing before pattern-matching:
  //   - Markdown bold/italic around the verdict (`**Yes**`, `*No*`).
  //   - Leading "## Heading" or "**Heading:**" preambles

/**
 * Matcher for Claude Code permission patterns.
 *
 * Mirrors Claude Code's own .permissions.{allow,deny,ask} syntax so the
 * lists the user already maintains in `.claude/settings.json` mean the
 * same thing inside Dredd as they do to Claude Code's permission UI.
 *
 * V1 syntax coverage (sufficient for the patterns that show up in the
 * Phase-1 uploads we've sampled):
 *
 *   "Tool"                       — any invocation of `Tool` (e.g. "Read")
 *   "Bash(prefix:*)"             — Bash command that starts with `prefix `
 *   "Read(<glob>)" / "Write(...)" / "Edit(<glob>)" — file_path matches glob
 *   "WebFetch(domain:<host>)"    — exact host match (no wildcards in v1)
 *   "mcp__server__tool"          — exact MCP tool-name match
 *
 * NOT in v1 (callers should expect false for these — we'll widen if real
 * uploads contain them):
 *   - Brace expansion in globs: "Read({src,test}/**)"
 *   - Bash regex-style arg matchers
 *   - MCP arg constraints beyond tool name
 *
 * Asymmetric semantics — two entry points:
 *   - matchUserAllow: for Bash, EVERY chained sub-command must match some
 *     rule. Stops "Bash(awk:*)" from authorising "awk x && curl evil.com".
 *   - matchUserDeny:  for Bash, ANY chained sub-command matching ANY deny
 *     rule is enough. Stops "Bash(rm:*)" deny being bypassed by
 *     "ls && rm -rf /".
 *   - For non-Bash tools both are symmetric — one rule match is enough.
 */

import { splitChainedSafely } from "./tool-policy.js";

export interface MatchResult {
  matched: boolean;
  /** First matching rule from the input list, "" when matched=false. */
  rule: string;
}

const NO_MATCH: MatchResult = { matched: false, rule: "" };

// ---------------------------------------------------------------------------
// Public entry points
// ---------------------------------------------------------------------------

/**
 * Does the user's allow list FULLY cover this tool call?
 *
 * For non-Bash tools: returns true iff any rule matches.
 * For Bash: returns true iff EVERY chained sub-command matches at least
 * one rule. Means "Bash(awk:*)" alone does NOT authorise
 * "awk x.txt && curl evil.com" — that needs BOTH "Bash(awk:*)" AND
 * "Bash(curl:*)" present.
 */
export function matchUserAllow(
  rules: string[],
  tool: string,
  input: Record<string, unknown>,
): MatchResult {
  if (!rules.length) return NO_MATCH;
  if (tool === "Bash") {
    return matchBashAllowAllParts(rules, input);
  }
  return matchNonBash(rules, tool, input);
}

/**
 * Does the user's deny list match this tool call?
 *
 * For non-Bash tools: returns true iff any rule matches.
 * For Bash: returns true iff ANY chained sub-command matches ANY rule
 * (the conservative direction — a deny-listed sub-command anywhere in
 * a pipeline still trips the deny).
 */
export function matchUserDeny(
  rules: string[],
  tool: string,
  input: Record<string, unknown>,
): MatchResult {
  if (!rules.length) return NO_MATCH;
  if (tool === "Bash") {
    return matchBashDenyAnyPart(rules, input);
  }
  return matchNonBash(rules, tool, input);
}

// ---------------------------------------------------------------------------
// Bash-specific matchers
// ---------------------------------------------------------------------------

/**
 * Every part of a chained command must be covered by some allow rule.
 * Empty / unparseable commands → no match (caller's allow list can't
 * approve nothing).
 */
function matchBashAllowAllParts(rules: string[], input: Record<string, unknown>): MatchResult {
  const command = typeof input.command === "string" ? input.command : "";
  if (!command.trim()) return NO_MATCH;

  // A bare "Bash" rule authorises any Bash call regardless of chain shape.
  const bareBash = rules.find((r) => r === "Bash");
  if (bareBash) return { matched: true, rule: bareBash };

  const parts = splitChainedSafely(command);
  if (parts.length === 0) return NO_MATCH;

  // Collect the first matching rule per part so failure can attribute
  // which part was the unmatched one. Success: return the first rule
  // that matched (gives the dashboard a representative rule to show).
  let firstMatchedRule = "";
  for (const part of parts) {
    const r = firstBashRuleMatching(rules, part);
    if (!r) return NO_MATCH;
    if (!firstMatchedRule) firstMatchedRule = r;
  }
  return { matched: true, rule: firstMatchedRule };
}

/**
 * Any part matching any rule denies the whole command.
 */
function matchBashDenyAnyPart(rules: string[], input: Record<string, unknown>): MatchResult {
  const command = typeof input.command === "string" ? input.command : "";
  if (!command.trim()) return NO_MATCH;

  // Bare "Bash" deny rule blocks everything outright.
  const bareBash = rules.find((r) => r === "Bash");
  if (bareBash) return { matched: true, rule: bareBash };

  for (const part of splitChainedSafely(command)) {
    const r = firstBashRuleMatching(rules, part);
    if (r) return { matched: true, rule: r };
  }
  return NO_MATCH;
}

/**
 * Walk the rules and return the first one matching this single
 * (un-chained) Bash sub-command, or undefined.
 */
function firstBashRuleMatching(rules: string[], subCommand: string): string | undefined {
  const trimmed = subCommand.trim();
  for (const rule of rules) {
    const prefix = parseBashPrefixRule(rule);
    if (prefix !== null && bashCommandHasPrefix(trimmed, prefix)) {
      return rule;
    }
  }
  return undefined;
}

/** Parse "Bash(prefix:*)" → "prefix". Returns null for other rule shapes. */
function parseBashPrefixRule(rule: string): string | null {
  const m = /^Bash\((.+):\*\)$/.exec(rule);
  if (!m) return null;
  return m[1];
}

/**
 * Does `command` start with `prefix` followed by a word boundary?
 * The boundary check prevents "Bash(awk:*)" from matching "awkward …".
 * End-of-string is also a valid boundary (a bare "awk" with no args).
 */
function bashCommandHasPrefix(command: string, prefix: string): boolean {
  if (!command.startsWith(prefix)) return false;
  if (command.length === prefix.length) return true;
  const next = command.charAt(prefix.length);
  // Whitespace or shell argument start is a word boundary; alphanumeric
  // or '-' (e.g. "awkward") is NOT.
  return /\s/.test(next);
}

// ---------------------------------------------------------------------------
// Non-Bash matcher
// ---------------------------------------------------------------------------

function matchNonBash(rules: string[], tool: string, input: Record<string, unknown>): MatchResult {
  for (const rule of rules) {
    if (matchSingleNonBashRule(rule, tool, input)) {
      return { matched: true, rule };
    }
  }
  return NO_MATCH;
}

function matchSingleNonBashRule(
  rule: string,
  tool: string,
  input: Record<string, unknown>,
): boolean {
  // Bare tool name — matches any invocation of that tool.
  if (rule === tool) return true;

  // MCP tools are exact name matches: "mcp__server__tool".
  if (rule.startsWith("mcp__")) {
    return rule === tool;
  }

  // Tool(arg) form.
  const m = /^(\w+)\((.+)\)$/.exec(rule);
  if (!m) return false;
  const [, ruleTool, body] = m;
  if (ruleTool !== tool) return false;

  // WebFetch(domain:<host>)
  if (tool === "WebFetch") {
    const dm = /^domain:(.+)$/.exec(body);
    if (!dm) return false;
    return hostMatchesWebFetch(input, dm[1]);
  }

  // Path-glob tools.
  if (tool === "Read" || tool === "Write" || tool === "Edit") {
    const path = typeof input.file_path === "string" ? input.file_path : "";
    if (!path) return false;
    return globMatches(body, path);
  }

  return false;
}

// ---------------------------------------------------------------------------
// WebFetch host extraction
// ---------------------------------------------------------------------------

function hostMatchesWebFetch(input: Record<string, unknown>, expected: string): boolean {
  const url = typeof input.url === "string" ? input.url : "";
  if (!url) return false;
  try {
    const u = new URL(url);
    return u.host.toLowerCase() === expected.toLowerCase();
  } catch {
    return false;
  }
}

// ---------------------------------------------------------------------------
// Glob → regex
// ---------------------------------------------------------------------------

/**
 * Minimal glob matcher for paths. Supports:
 *   *   any run of chars except `/`
 *   **  any run of chars including `/`
 *   ?   one char that isn't `/`
 *   anything else is literal (regex-escaped)
 *
 * `~` prefixes are expanded to $HOME when present in the rule. This
 * matches the convention that surfaces in Claude Code settings.json.
 */
export function globMatches(pattern: string, path: string): boolean {
  return globToRegex(expandHome(pattern)).test(expandHome(path));
}

function expandHome(p: string): string {
  if (!p.startsWith("~")) return p;
  const home = process.env.HOME ?? "";
  return home ? home + p.slice(1) : p;
}

function globToRegex(glob: string): RegExp {
  // Tokenise to keep `**` distinguishable from `*` BEFORE we escape
  // regex specials inside the literal slices.
  let regex = "";
  let i = 0;
  while (i < glob.length) {
    const c = glob[i];
    if (c === "*") {
      if (glob[i + 1] === "*") {
        regex += ".*";
        i += 2;
      } else {
        regex += "[^/]*";
        i += 1;
      }
    } else if (c === "?") {
      regex += "[^/]";
      i += 1;
    } else {
      regex += c.replace(/[.+^${}()|[\]\\]/g, "\\$&");
      i += 1;
    }
  }
  return new RegExp(`^${regex}$`);
}

/**
 * Tool Policy Engine
 *
 * Classifies tool calls into three categories:
 *   ALLOW  — always permitted, no review (read-only, search, navigation)
 *   DENY   — always blocked, never permitted (destructive, dangerous)
 *   REVIEW — requires intent evaluation before proceeding
 *
 * Operates at the PreToolUse level, evaluating tool name + parameters
 * before execution. Fast pattern matching — no LLM calls.
 *
 * The pattern tables themselves live in `policy-patterns.ts` so they
 * can be browsed independently of the engine logic. Re-exported here
 * for backwards compatibility with existing import sites.
 */

import {
  type PatternRule,
  ALLOWED_TOOLS,
  ALLOWED_BASH_PATTERNS,
  DENIED_BASH_PATTERNS,
  REVIEW_BASH_PATTERNS,
  SENSITIVE_FILE_PATTERNS,
  SENSITIVE_WRITE_PATTERNS,
} from "./policy-patterns.js";

export {
  ALLOWED_TOOLS,
  ALLOWED_BASH_PATTERNS,
  DENIED_BASH_PATTERNS,
  REVIEW_BASH_PATTERNS,
  SENSITIVE_FILE_PATTERNS,
  SENSITIVE_WRITE_PATTERNS,
};
export type { PatternRule };

export type PolicyDecision = "allow" | "deny" | "review";

export interface PolicyResult {
  decision: PolicyDecision;
  tool: string;
  reason: string;
  /** The matched rule that triggered this decision */
  matchedRule: string;
}


/**
 * Allow-listed command substitutions that are safe to embed in a git
 * commit/tag message. A substitution inside a commit message executes at
 * shell expansion time — before git sees the message — so each entry is
 * effectively "this command is OK to run as a side effect of committing."
 *
 * Extending the list: add a RegExp whose content matches the INNER text of
 * the substitution (between `$(...)` / backticks). Keep it narrow — the
 * whole point is that anything not on the list goes through the judge.
 */
const SAFE_COMMIT_SUBSTITUTIONS: RegExp[] = [
  // Dates / timestamps
  /^date(\s+[+][^;|&`$<>]*)?$/,         // date, date +%Y-%m-%d, etc.
  /^date\s+-u(\s+[+][^;|&`$<>]*)?$/,    // date -u +...
  /^date\s+--iso-8601(=\w+)?$/,         // date --iso-8601
  // Git metadata — safe because "git" is not the destructive surface
  /^git\s+rev-parse\s+(--short\s+)?HEAD$/,
  /^git\s+rev-parse\s+(--short\s+)?--verify\s+HEAD$/,
  /^git\s+describe(\s+--tags)?(\s+--always)?$/,
  /^git\s+rev-list\s+--count\s+HEAD$/,
  // Whoami / hostname
  /^whoami$/,
  /^hostname(\s+-\w+)?$/,
  // Version fields
  /^cat\s+VERSION$/,
];

/**
 * Does the text (already extracted from `$(...)` or backticks) match one of
 * the allow-listed safe substitutions? Used by the git-commit sanitiser.
 *
 * Special case: `cat <<'TAG' ... TAG` with a SINGLE-QUOTED heredoc delimiter
 * is equivalent to a literal multi-line string — the shell performs no
 * expansion inside the body. It's the canonical idiom for long commit
 * messages (`git commit -m "$(cat <<'EOF' … EOF)"`). We recognise the
 * shape here and treat it as safe regardless of body contents.
 */
function isSafeCommitSubstitution(inner: string): boolean {
  const trimmed = inner.trim();
  if (SAFE_COMMIT_SUBSTITUTIONS.some((re) => re.test(trimmed))) return true;
  // cat <<'TAG' \n ... \n TAG  — single-quoted tag disables expansion
  const safeHeredoc = /^cat\s+<<-?'(\w+)'\s*\n[\s\S]*\n\s*\1\s*$/;
  if (safeHeredoc.test(trimmed)) return true;
  return false;
}

/**
 * Extract every `$(...)` and `` `...` `` substitution from the commit-message
 * argument(s) of a git commit/tag command. Returns the inner contents.
 *
 * We only scan the portion of the command that is the commit MESSAGE so
 * that unrelated substitutions elsewhere in the command (e.g. in
 * `git commit --author=$(whoami)`) aren't swept by this check — they're
 * still inspected by the normal review rule for `$(` at the top level.
 */
function extractCommitMessageSubstitutions(command: string): string[] {
  const out: string[] = [];
  // -m "..." / -m '...' — quoted message arg
  const mArgs = [
    ...command.matchAll(/\s-m\s+"((?:[^"\\]|\\.)*)"/g),
    ...command.matchAll(/\s-m\s+'((?:[^'\\]|\\.)*)'/g),
    ...command.matchAll(/\s-m=("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\S+)/g),
    ...command.matchAll(/\s--message=("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\S+)/g),
  ];
  for (const m of mArgs) {
    const body = m[1].replace(/^['"]|['"]$/g, "");
    // $( ... ) with simple nesting-free parens
    for (const sub of body.matchAll(/\$\(([^()]*)\)/g)) out.push(sub[1]);
    // backtick substitution
    for (const sub of body.matchAll(/`([^`]*)`/g)) out.push(sub[1]);
  }
  // Heredoc-fed messages: `git commit -F - <<EOF … EOF` or
  // `-m "$(cat <<EOF … EOF)"`. Substitutions inside heredoc bodies
  // execute at shell expansion time UNLESS the tag is quoted (single
  // or double): `<<'EOF'` and `<<"EOF"` both disable expansion, so
  // `$(...)` and `` `...` `` in those bodies are literal text. Skip
  // the extraction for quoted tags — otherwise the policy false-
  // positives on commit-message prose that uses backticks for code
  // markdown formatting (a common pattern).
  const heredocs = command.matchAll(/<<-?\s*(['"]?)(\w+)\1\s*\n([\s\S]*?)\n\s*\2(?=\s|$)/g);
  for (const h of heredocs) {
    const tagQuote = h[1];
    if (tagQuote === "'" || tagQuote === '"') continue;
    const body = h[3];
    for (const sub of body.matchAll(/\$\(([^()]*)\)/g)) out.push(sub[1]);
    for (const sub of body.matchAll(/`([^`]*)`/g)) out.push(sub[1]);
  }
  return out;
}

/**
 * Is `command` an invocation of `git <subcommand>` from the given list,
 * allowing for git's global flags (`-C <path>`, `-c key=val`, `--git-dir=`,
 * `--work-tree=`, `--no-pager`, etc.) between `git` and the subcommand?
 *
 * The previous version matched only `^git\s+(commit|tag)\b`, which misses
 * common forms like `git -C /path commit -m ...` — the `-C <path>` global
 * option comes before the subcommand. Without detection, sanitisation
 * below never fires and free-form commit message bodies are swept by
 * deny rules like `\benv\b` ("Dump environment").
 */
function isGitSubcommand(command: string, subcommands: readonly string[]): boolean {
  const trimmed = command.trim();
  if (!/^git(\s|$)/.test(trimmed)) return false;

  // Tokens after the literal "git". Simple whitespace split is fine here
  // because we're only scanning up to the first non-flag token; anything
  // past that (args, quoted messages, heredocs) doesn't matter for this
  // check.
  const tokens = trimmed.split(/\s+/).slice(1);
  let i = 0;
  while (i < tokens.length) {
    const t = tokens[i];
    if (!t.startsWith("-")) {
      return subcommands.includes(t);
    }
    // -C <path> and -c <key=val> take a value in the NEXT token when
    // no `=` is fused into the flag itself.
    if ((t === "-C" || t === "-c") && !t.includes("=")) {
      i += 2; continue;
    }
    // Long options: `--long=value` is self-contained; `--long value`
    // requires the next token. We conservatively assume bare long
    // flags are boolean and skip only 1 token — worst case this over-
    // consumes nothing and we find the subcommand one token later.
    i += 1;
  }
  return false;
}

/**
 * Git commit/tag messages are free-form text that often legitimately contains
 * strings like destructive-delete commands or bare words like "env var" when
 * describing a change. Those are payload, not executable — but naive regex
 * matching over the raw command trips deny rules on them. This strips the
 * message body (returning a placeholder) so pattern matching sees only the
 * actual invocation.
 *
 * Only applied to `git commit` / `git tag`; every other command is returned
 * unchanged so heredoc bodies (e.g. `bash <<EOF ... EOF`) still deny on
 * dangerous content.
 */
function sanitizeForMatching(command: string): string {
  if (!isGitSubcommand(command, ["commit", "tag"])) return command;

  let s = command;
  // -m "..." / -m '...' — quoted message arg.
  s = s.replace(/\s-m\s+"(?:[^"\\]|\\.)*"/g, ' -m "<msg>"');
  s = s.replace(/\s-m\s+'(?:[^'\\]|\\.)*'/g, " -m '<msg>'");
  // --message="..." / --message='...' / --message=bare
  s = s.replace(/\s--message=(?:"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\S+)/g, " --message=<msg>");
  // -m=... variants.
  s = s.replace(/\s-m=(?:"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\S+)/g, " -m=<msg>");
  // Heredoc bodies: <<EOF ... EOF / <<-EOF ... EOF / <<'EOF' ... EOF
  //
  // NOTE: we deliberately do NOT strip `$(...)` or backticks anywhere. They
  // execute at shell expansion time, before git even runs — so they are
  // commands, not message prose. `checkCommitMessageSubstitutions` evaluates
  // them against SAFE_COMMIT_SUBSTITUTIONS ahead of this sanitiser; anything
  // that got past that is either safe or the command has already been denied.
  s = s.replace(/<<-?\s*(['"]?)(\w+)\1\s*\n[\s\S]*?\n\2\s*/g, "<<$2\n<msg>\n$2\n");

  return s;
}

/**
 * For `git commit` / `git tag`: enforce the rule that command substitutions
 * inside the message body are only allowed if they match the
 * SAFE_COMMIT_SUBSTITUTIONS list. Returns a deny result if any substitution
 * is not on the list, null if the command is fine (or isn't a git commit).
 */
function checkCommitMessageSubstitutions(command: string): SingleBashResult | null {
  if (!isGitSubcommand(command, ["commit", "tag"])) return null;
  const subs = extractCommitMessageSubstitutions(command);
  if (subs.length === 0) return null;
  for (const s of subs) {
    if (!isSafeCommitSubstitution(s)) {
      return {
        decision: "deny",
        reason: `Unsafe command substitution in git commit message: \`${s.substring(0, 60)}\``,
        matchedRule: "DENY:Bash:commit-msg-subst-unsafe",
        command,
      };
    }
  }
  return null;
}

/**
 * Split `command` on top-level chain operators (`&&`, `||`, `;`, `|`) while
 * treating heredoc bodies, command substitutions, backticks, and quoted
 * strings as opaque tokens.
 *
 * A naive `command.split(/&&|\|\||;|\|/)` finds chain operators inside
 * quoted strings and heredoc bodies — which is wrong. For example:
 *
 *   git commit -m "$(cat <<'EOF

/**
 * Ollama Client
 *
 * Lightweight HTTP client for Ollama's local API.
 * Provides embedding generation and chat completion
 * without any external dependencies.
 */

const OLLAMA_BASE = process.env.OLLAMA_HOST ?? "http://localhost:11434";

export interface EmbeddingResponse {
  embeddings: number[][];
}

export interface ChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
  /** Base64-encoded images (Ollama vision models only) */
  images?: string[];
}

export interface ChatResponse {
  message: {
    role: string;
    content: string;
  };
  total_duration?: number;
  eval_count?: number;
}

/**
 * Generate embeddings for one or more texts.
 */
export async function embed(
  texts: string | string[],
  model = "nomic-embed-text"
): Promise<number[][]> {
  const input = Array.isArray(texts) ? texts : [texts];

  const res = await fetch(`${OLLAMA_BASE}/api/embed`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model, input }),
  });

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Ollama embed failed (${res.status}): ${body}`);
  }

  const data = (await res.json()) as EmbeddingResponse;
  return data.embeddings;
}

/**
 * Chat completion with a local model. Streaming disabled for simplicity.
 */
export async function chat(
  messages: ChatMessage[],
  model = "llama3.2"
): Promise<{ content: string; durationMs: number }> {
  const start = Date.now();

  const res = await fetch(`${OLLAMA_BASE}/api/chat`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model, messages, stream: false }),
  });

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Ollama chat failed (${res.status}): ${body}`);
  }

  const data = (await res.json()) as ChatResponse;
  return {
    content: data.message.content,
    durationMs: Date.now() - start,
  };
}

/**
 * Route an embed call to Bedrock or Ollama based on the model name.
 * Bedrock model IDs start with a known provider prefix (with or without a
 * region qualifier like eu./us./global.). Ollama model names never do.
 */
const BEDROCK_PREFIXES = /^(?:eu\.|us\.|global\.|amazon\.|cohere\.|twelvelabs\.|anthropic\.|meta\.|mistral\.|nvidia\.)/;

export function isBedrockModel(model: string): boolean {
  return BEDROCK_PREFIXES.test(model);
}

export async function embedAny(
  texts: string | string[],
  model: string
): Promise<number[][]> {
  if (isBedrockModel(model)) {
    const { bedrockEmbed } = await import("./bedrock-client.js");
    const arr = Array.isArray(texts) ? texts : [texts];
    return bedrockEmbed(arr, model);
  }
  return embed(texts, model);
}

/**
 * Cosine similarity between two vectors.
 */
export function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length !== b.length) {
    throw new Error(`Vector dimension mismatch: ${a.length} vs ${b.length}`);
  }
  let dot = 0;
  let normA = 0;
  let normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom === 0 ? 0 : dot / denom;
}

/**
 * Check if Ollama is reachable and the required models are available.
 */
export async function checkOllama(
  embeddingModel: string,
  chatModel?: string
): Promise<{ ok: boolean; missing: string[] }> {
  const required = chatModel ? [embeddingModel, chatModel] : [embeddingModel];
  try {
    const res = await fetch(`${OLLAMA_BASE}/api/tags`);
    if (!res.ok) return { ok: false, missing: required };

    const data = (await res.json()) as { models: { name: string }[] };
    const available = new Set(data.models.map((m) => m.name.split(":")[0]));

    const missing: string[] = [];
    for (const m of required) {
      if (!available.has(m.split(":")[0])) missing.push(m);
    }

    return { ok: missing.length === 0, missing };
  } catch {
    return { ok: false, missing: required };
  }
}

