/**
 * OpenAI Client — minimal chat-completions wrapper.
 *
 * Used by PromptArmorBaseline (and any future OpenAI-backed feature) for
 * single-call detector-style requests: system prompt + one user message,
 * no tools, no streaming, deterministic temperature. Mirrors the
 * shape of bedrock-client.ts so callers can swap backends with the
 * same surface.
 *
 * Uses the global fetch (Node 22+) to avoid adding the openai SDK as
 * a runtime dependency. The chat-completions API surface is stable
 * enough for this.
 *
 * Caller responsibilities:
 *   - Set OPENAI_API_KEY in env. We do not read this at module load
 *     so the absence is a per-call failure rather than a startup crash.
 *   - Pick the model. We don't map friendly aliases here (executor-
 *     openai.ts has a MODEL_MAP for that — caller-side concern).
 */

interface OpenAIChatResponse {
  choices: Array<{
    message: { content: string | null };
    finish_reason: string;
  }>;
  usage: {
    prompt_tokens: number;
    completion_tokens: number;
    total_tokens: number;
  };
}

export interface OpenAIChatResult {
  content: string;
  durationMs: number;
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
  finishReason: string;
}

export async function openaiChat(
  systemPrompt: string,
  userMessage: string,
  modelId: string,
  opts: {
    /** Defaults to 0 for deterministic detector-style use. */
    temperature?: number;
    /** Cap on output tokens. */
    maxTokens?: number;
    /** Per-call abort timeout in ms; default 60s. */
    timeoutMs?: number;
  } = {},
): Promise<OpenAIChatResult> {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) {
    throw new Error("OPENAI_API_KEY not set");
  }

  const body = {
    model: modelId,
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userMessage },
    ],
    temperature: opts.temperature ?? 0,
    max_tokens: opts.maxTokens ?? 256,
  };

  const start = Date.now();
  const maxAttempts = 3;
  let lastErr: Error | null = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const res = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(opts.timeoutMs ?? 60_000),
      });

      if (!res.ok) {
        const text = await res.text().catch(() => "");
        if ((res.status === 429 || res.status >= 500) && attempt < maxAttempts) {
          const backoff = 1000 * Math.pow(2, attempt - 1);
          console.warn(
            `  [openai ${res.status}] attempt ${attempt}/${maxAttempts}; sleeping ${backoff}ms`,
          );
          await new Promise((r) => setTimeout(r, backoff));
          continue;
        }
        throw new Error(`OpenAI HTTP ${res.status}: ${text.substring(0, 500)}`);
      }

      const json = (await res.json()) as OpenAIChatResponse;
      const choice = json.choices?.[0];
      const content = choice?.message?.content ?? "";
      const usage = json.usage ?? { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 };
      return {
        content,
        durationMs: Date.now() - start,
        inputTokens: usage.prompt_tokens,
        outputTokens: usage.completion_tokens,
        totalTokens: usage.total_tokens,
        finishReason: choice?.finish_reason ?? "unknown",
      };
    } catch (err) {
      lastErr = err instanceof Error ? err : new Error(String(err));
      if (attempt < maxAttempts) {
        const backoff = 1000 * Math.pow(2, attempt - 1);
        console.warn(
          `  [openai fetch] attempt ${attempt}/${maxAttempts}: ${lastErr.message}; sleeping ${backoff}ms`,
        );
        await new Promise((r) => setTimeout(r, backoff));
        continue;
      }
    }
  }
  throw lastErr ?? new Error("OpenAI call failed with no captured error");
}

/**
 * Write-through LRU cache wrapping an `ApiKeyStore`.
 *
 * API keys are validated on EVERY hook request. That's potentially the
 * hottest path in the server — every tool call, every intent registration,
 * every /track, every /end. Doing a Dynamo `GetItem` for each would add
 * ~10ms p50 + a Dynamo read for every request. With a positive cache of a
 * few minutes we take the hit once per key per container and serve the
 * rest from memory.
 *
 * Two caches:
 *   - positive: validated hash → ValidatedKey, 5m TTL. Reverts to Dynamo
 *                after TTL so revocations eventually propagate.
 *   - negative: unknown hash → tombstone, 30s TTL. Stops an attacker from
 *                brute-forcing keys by ensuring each guess pays a Dynamo
 *                lookup at most once per 30s per hash.
 *
 * Revocation propagation:
 *   - The container that calls `revokeKey` invalidates its own cache
 *     immediately.
 *   - Other containers stay stale for up to 5 minutes (positive cache TTL).
 *     For the sandbox threat model this is acceptable; emergency revoke
 *     within 5 minutes is fine. If we need faster, we'd add an SNS fanout
 *     invalidation channel — out of scope for v1.
 *
 * lastUsedAt:
 *   - The backend updates lastUsedAt asynchronously on every `validateKey`.
 *     We don't bother reading it on cache hits (it's only for dashboard
 *     display, not for security decisions), so cache staleness is fine.
 */

import {
  type ApiKeyStore,
  type GenerateKeyInput,
  type GeneratedKey,
  type KeyRecord,
  type ValidatedKey,
  hashKey,
  looksLikeJaidKey,
} from "./api-key-store.js";

const POSITIVE_TTL_MS = 5 * 60 * 1000;
const NEGATIVE_TTL_MS = 30 * 1000;
const DEFAULT_MAX = 1000;

interface CacheEntry {
  validated: ValidatedKey | null; // null = tombstone (known-unknown)
  expiresAt: number;
}

export interface CachedApiKeyStoreOptions {
  backend: ApiKeyStore;
  maxHashes?: number;
  positiveTtlMs?: number;
  negativeTtlMs?: number;
  /** Override for tests. */
  now?: () => number;
}

export class CachedApiKeyStore implements ApiKeyStore {
  private readonly backend: ApiKeyStore;
  private readonly maxHashes: number;
  private readonly positiveTtlMs: number;
  private readonly negativeTtlMs: number;
  private readonly now: () => number;

