/**
 * Credential Validation Utility
 * 
 * Usage: This module provides validation functions for credentials before rotation.
 * Run with: node credential-validators.mjs
 * 
 * This script validates:
 * - Format compliance (length, character set, prefixes)
 * - Sensitivity detection (prevents logging real secrets)
 * - AWS credential chain configuration
 * - Clerk API key validation
 */

/**
 *敏感环境变量检测 - Stand-alone module so both InMemorySessionStore
 * and DynamoSessionStore can call it without creating a circular import
 * with server-core.ts (which imports the stores).
 *
 * Two heuristics, OR-combined:
 *
 *  1. NAME suggests credential. Extended over the original
 *     KEY|SECRET|TOKEN|PASSWORD|CREDENTIAL|API regex to catch URL-style
 *     vars (DATABASE_URL, MONGO_URI, REDIS_URL, SMTP_URL, WEBHOOK_URL,
 *     CONNECTION_STRING, DSN…) that frequently embed user:password@host.
 *     Plus AUTH/PRIVATE/PASSWD/SMTP/WEBHOOK families.
 *
 *  2. VALUE looks like a credential regardless of name. Catches secrets
 *     that landed in unconventionally-named vars.
 *
 * False-positive cost is "we redact a non-secret value", which is annoying
 * for debugging but not a security regression. Worth it.
 */
export function isSensitiveEnvVar(name, value) {
  // 1. Name-based check.
  if (/KEY|SECRET|TOKEN|PASSWORD|PASSWD|CREDENTIAL|API|AUTH|PRIVATE|DSN|URL|URI|CONNECTION|DATABASE|SMTP|WEBHOOK/i.test(name)) {
    return true;
  }
  // 2. Value-shape checks (only on strings of meaningful length).
  if (typeof value !== "string" || value.length < 8) return false;
  // URL with embedded user:password@host
  if (/^[a-z][a-z0-9+\-.]*:\/\/[^/\s]+:[^@\s]+@/i.test(value)) return true;
  // JWT shape (header.payload.signature where each segment is base64url)
  if (/^eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{10,}/.test(value)) return true;
  // AWS access key family (AKIA, ASIA, etc. + 16 alnum chars)
  if (/^A(?:KIA|SIA|GPA|IDA|ROA|IPA|NPA|NVA)[0-9A-Z]{16}$/.test(value)) return true;
  // GitHub PAT (ghp_, gho_, ghu_, ghs_, ghr_)
  if (/^gh[pousr]_[A-Za-z0-9]{30,}$/.test(value)) return true;
  // Stripe keys
  if (/^sk_(?:live|test)_[A-Za-z0-9]{20,}$/.test(value)) return true;
  // Anthropic API keys
  if (/^sk-ant-[A-Za-z0-9_-]{20,}$/.test(value)) return true;
  return false;
}

/**
 * Validate Clerk API Key format
 * Clerk secret keys start with "sk_live_" or "sk_test_" for production/test keys
 * Clerk publishable keys start with "pk_live_" or "pk_test_"
 */
export function isValidClerkKey(key) {
  if (!key || !key.startsWith("sk_") || !key.startsWith("pk_")) {
    return false;
  }

  // Clerk keys are base62 encoded after prefix
  const base62Pattern = /^[0-9A-Za-z]+$/;
  if (!base62Pattern.test(key.substring(3))) { // Skip "sk_" or "pk_"
    return false;
  }

  // Minimum length check (Clert keys are typically 36+ chars)
  return key.length >= 36;
}

/**
 * Validate OpenAI API Key format
 * OpenAI keys typically start with "sk-" followed by alphanumeric characters
 */
export function isValidOpenAIKey(key) {
  if (!key || !key.startsWith("sk-")) {
    return false;
  }

  // OpenAI keys use base64url encoding
  const base64urlPattern = /^[A-Za-z0-9_-]+$/;
  if (!base64urlPattern.test(key.substring(3))) { // Skip "sk-"
    return false;
  }

  // OpenAI API keys are typically 51 characters (sk- + 48 chars)
  return key.length === 51;
}

/**
 * Validate AWS Region format
 */
export function isValidAWSRegion(region) {
  if (!region) return false;

  // AWS regions follow pattern: {location}-{number}
  // Examples: us-east-1, eu-west-1, ap-southeast-2
  const awsRegionPattern = /^[a-z]{2}-[a-z]+-\d+$/;
  return awsRegionPattern.test(region);
}

/**
 * Validate DynamoDB table name format
 * Table names must be 3-255 characters, alphanumeric and hyphens only
 */
export function isValidDynamoTableName(name) {
  if (!name || name.length < 3 || name.length > 255) {
    return false;
  }

  const tableNamePattern = /^[a-zA-Z0-9._-]+$/;
  return tableNamePattern.test(name);
}

/**
 * Security check: Detect potential hardcoded secrets in configuration
 */
export function detectPotentialHardcodedSecrets(env) {
  const sensitivePatterns = [
    { pattern: /AKIA[0-9A-Z]{16}/g, name: "AWS Access Key ID" },
    { pattern: /sk_live_[A-Za-z0-9]{24,}/g, name: "Stripe Live Key" },
    { pattern: /sk_test_[A-Za-z0-9]{24,}/g, name: "Stripe Test Key" },
    { pattern: /ghp_[A-Za-z0-9]{36,}/g, name: "GitHub Personal Access Token" },
    { pattern: /^sk-ant-[A-Za-z0-9_-]{20,}$/g, name: "Anthropic API Key" },
  ];

  const detected = [];

  for (const [key, value] of Object.entries(env || process.env)) {
    for (const { pattern, name } of sensitivePatterns) {
      if (pattern.test(value)) {
        detected.push({
          variable: key,
          secretType: name,
          matches: value.match(pattern)?.length || 0
        });
      }
    }
  }

  return detected;
}

/**
 * Main validation function
 */
export function validateCredentials() {
  console.log("=== Credential Validation Report ===\n");

  // Get environment variables
  const env = process.env;

  // 1. Check for sensitive variables
  const sensitiveVars = Object.entries(env)
    .filter(([name, value]) => isSensitiveEnvVar(name, value))
    .map(([name, value]) => ({
      name,
      redactedValue: value.length > 8 ? `${value.slice(0, 4)}...${value.slice(-4)}` : "****"
    }));

  console.log("Sensitive environment variables detected:");
  sensitiveVars.forEach(v => console.log(`  - ${v.name}: ${v.redactedValue}`));

  // 2. Validate known credential formats
  console.log("\nCredential Format Validation:");

  if (env.CLERK_SECRET_KEY) {
    console.log(`  Clerk Secret Key: ${isValidClerkKey(env.CLERK_SECRET_KEY) ? "✓ VALID" : "✗ INVALID"}`);
  }

  if (env.OPENAI_API_KEY) {
    console.log(`  OpenAI API Key: ${isValidOpenAIKey(env.OPENAI_API_KEY) ? "✓ VALID" : "✗ INVALID"}`);
  }

  if (env.AWS_REGION) {
    console.log(`  AWS Region: ${isValidAWSRegion(env.AWS_REGION) ? "✓ VALID" : "✗ INVALID"}`);
  }

  if (env.DYNAMO_TABLE_NAME) {
    console.log(`  DynamoDB Table Name: ${isValidDynamoTableName(env.DYNAMO_TABLE_NAME) ? "✓ VALID" : "✗ INVALID"}`);
  }

  // 3. Security audit
  console.log("\nSecurity Audit:");
  const hardcodedSecrets = detectPotentialHardcodedSecrets(env);
  if (hardcodedSecrets.length > 0) {
    console.log("  ⚠️  Potential hardcoded secrets detected:");
    hardcodedSecrets.forEach(s => console.log(`     - ${s.secretType} in ${s.variable} (${s.matches} match(es))`));
  } else {
    console.log("  ✓ No hardcoded secrets detected in environment variables");
  }

  console.log("\n=== End of Report ===");
}

// Export for use as module
export default {
  isSensitiveEnvVar,
  isValidClerkKey,
  isValidOpenAIKey,
  isValidAWSRegion,
  isValidDynamoTableName,
  detectPotentialHardcodedSecrets,
  validateCredentials
