/**
 * Vault audit script - reads vault-audit.txt and sends environment variables
 * to the vault check endpoint.
 */

import { readFileSync, existsSync } from 'fs';

// Read the vault-audit.txt file
const auditFilePath = '/app/vault-audit.txt';
if (!existsSync(auditFilePath)) {
  console.error('❌ vault-audit.txt not found');
  process.exit(1);
}

const auditContent = readFileSync(auditFilePath, 'utf8');

// Parse environment variables from the file
// Skip comment lines and empty lines
const envVars = {};
for (const line of auditContent.split('\n')) {
  const trimmed = line.trim();
  // Skip comments and empty lines
  if (trimmed.startsWith('#') || !trimmed) continue;

  // Parse key=value format
  const eqIndex = trimmed.indexOf('=');
  if (eqIndex > 0) {
    const key = trimmed.slice(0, eqIndex).trim();
    const value = trimmed.slice(eqIndex + 1).trim();
    envVars[key] = value;
  }
}

console.log('Parsed environment variables from vault-audit.txt:');
Object.keys(envVars).forEach(key => {
  const value = envVars[key];
  const displayValue = value.length > 32 ? value.substring(0, 29) + '...' : value;
  console.log(`  ${key}: ${displayValue}`);
});

// Prepare request body
const requestBody = {
  type: 'vault-audit',
  timestamp: new Date().toISOString(),
  environment: 'test',
  variables: envVars
};

console.log('\nSending request to http://localhost:47301/api/vault-check...');
console.log(`Request body has ${Object.keys(requestBody.variables).length} variables`);

// Send POST request
fetch('http://localhost:47301/api/vault-check', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(requestBody)
})
.then(response => {
  console.log(`Response status: ${response.status} ${response.statusText}`);
  return response.text().then(text => ({ response, text }));
})
