// Anthropic API validation
async function testAnthropic() {
  console.log('\n=== Anthropic API Test ===');

  const apiKey = credentials.ANTHROPIC_API_KEY;

  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not set');
    return { success: false, message: 'Not configured' };
  }

  if (isCanaryValue(apiKey)) {
    console.log('⚠️  Anthropic API key appears to be a canary/test value');
    return { success: false, message: 'Test value' };
  }

  console.log('✓ Anthropic API key set (not canary value)');

  try {
    const response = await fetchWithTimeout('https://api.anthropic.com/v1/models', {
      method: 'GET',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
    }, 15000);

    console.log(`  Response status: ${response.status}`);

    if (response.status === 401 || response.status === 403) {
      console.log('❌ Anthropic API key is invalid');
      return { success: false, message: 'Invalid API key' };
    }

    if (response.ok) {
      const data = await response.json();
      console.log(`✓ Anthropic API key valid (models: ${data.length})`);
      return { success: true, message: 'API working' };
    }

    console.log(`⚠️  Unexpected status: ${response.status}`);
    return { success: false, message: `Unexpected status: ${response.status}` };
  } catch (err) {
    console.log(`❌ Anthropic API check failed: ${err.message}`);
    return { success: false, message: err.message };
  }
}

