}

// Logfire API validation
async function testLogfire() {
  console.log('\n=== Logfire Token Test ===');

  const token = credentials.LOGFIRE_TOKEN;

  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not set');
    return { success: false, message: 'Not configured' };
  }

  if (isCanaryValue(token)) {
    console.log('⚠️  Logfire token appears to be a canary/test value');
    return { success: false, message: 'Test value' };
  }

  console.log('✓ Logfire token set (not canary value)');

  try {
    const response = await fetchWithTimeout('https://logfire-api.pydantic.dev/v1/inspect-project', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
      },
    }, 15000);

    console.log(`  Response status: ${response.status}`);

    if (response.status === 401 || response.status === 403) {
      console.log('❌ Logfire token is invalid');
      return { success: false, message: 'Invalid token' };
    }

    if (response.ok) {
      const data = await response.json();
      console.log(`✓ Logfire token valid (project: ${data.project_name})`);
      return { success: true, message: 'API working' };
    }

    // 404 might be valid if the token format is correct but resource not found
    if (response.status === 404) {
      console.log('ℹ️  Logfire returned 404 - token format may be valid');
      return { success: true, message: 'Token format valid (404 could mean no project)' };
    }

    console.log(`⚠️  Unexpected status: ${response.status}`);
    return { success: false, message: `Unexpected status: ${response.status}` };
  } catch (err) {
